7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      color-scheme: light dark;
19	      --bg: #fff;
20	      --text: #374151;
21	      --fg: #2563eb;
22	      --shadow: rgba(0, 0, 0, 0.1);
23	      --kbd-bg: rgba(0, 0, 0, 0.1);
24	    }
25	    [data-color="red"] { --fg: #dc2626; }
26	    [data-color="green"] { --fg: #16a34a; }
27	    [data-color="amber"] { --fg: #d97706; }
28	    [data-color="violet"] { --fg: #7c3aed; }
29	    [data-color="cyan"] { --fg: #0891b2; }
30	    @media (prefers-color-scheme: dark) {
31	      :root {
32	        --bg: #111;
33	        --text: #d1d5db;
34	        --fg: #93c5fd;
35	        --shadow: rgba(0, 0, 0, 0.6);
36	        --kbd-bg: rgba(255, 255, 255, 0.15);
37	      }
38	      [data-color="red"] { --fg: #fca5a5; }
39	      [data-color="green"] { --fg: #86efac; }
40	      [data-color="amber"] { --fg: #fcd34d; }
41	      [data-color="violet"] { --fg: #c4b5fd; }
42	      [data-color="cyan"] { --fg: #67e8f9; }
43	    }
44	    @media (prefers-contrast: more) {
45	      :root {
46	        --shadow: rgba(0, 0, 0, 0.9);
47	      }
48	      .hint {
49	        opacity: 1;
50	      }
51	    }
52	    @media (forced-colors: active) {
53	      svg circle {
54	        stroke: CanvasText;
55	        stroke-width: 2;
56	      }
57	    }
58	    body {
59	      min-height: 100vh;
60	      min-height: 100dvh;
61	      display: grid;
62	      place-items: center;
63	      padding: 1rem;
64	      background: var(--bg);
65	      color: var(--text);
66	      font-family: system-ui, -apple-system, sans-serif;
67	    }
68	    main {
69	      width: 100%;
70	      display: flex;
71	      flex-direction: column;
72	      align-items: center;
73	      text-align: center;
74	    }
75	    button {
76	      display: block;
77	      width: min(360px, 100%, 60vh);
78	      aspect-ratio: 1;
79	      border: 0;
80	      border-radius: 50%;
81	      background: none;
82	      color: var(--fg);
83	      cursor: pointer;
84	      touch-action: manipulation;
85	      -webkit-tap-highlight-color: transparent;
86	      transition: color 0.4s ease;
87	    }
88	    button:focus-visible {
89	      outline: 3px solid var(--fg);
90	      outline-offset: 8px;
91	    }
92	    svg {
93	      display: block;
94	      width: 100%;
95	      height: 100%;
96	      overflow: visible;
97	      opacity: 0.9;
98	      filter: drop-shadow(0 8px 16px var(--shadow));
99	      transition: opacity 0.3s ease;
100	    }
101	    button:active svg,
102	    button:focus-visible svg {
103	      opacity: 1;
104	    }
105	    @keyframes pulse {
106	      0% {
107	        filter: drop-shadow(0 8px 16px var(--shadow)) drop-shadow(0 0 20px var(--fg));
108	      }
109	      100% {
110	        filter: drop-shadow(0 8px 16px var(--shadow));
111	      }
112	    }
113	    @media (hover: hover) {
114	      button:hover svg {
115	        opacity: 1;
116	      }
117	    }
118	    @media (prefers-reduced-motion: no-preference) {
119	      svg {
120	        transition:
121	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
122	          opacity 0.3s ease;
123	      }
124	      button:focus-visible svg {
125	        transform: scale(1.05);
126	      }
127	      button:active svg {
128	        transform: scale(0.97);
129	      }
130	      button.color-changed svg {
131	        animation: pulse 0.5s ease-out;
132	      }
133	    }
134	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
135	      button:hover:not(:active) svg {
136	        transform: scale(1.05);
137	      }
138	    }
139	    .status {
140	      margin-top: 2rem;
141	      font-weight: 600;
142	    }
143	    .hint {
144	      margin-top: 0.25rem;
145	      font-size: 0.875rem;
146	      opacity: 0.8;
147	    }
148	    kbd {
149	      display: inline-block;
150	      padding: 0.125rem 0.375rem;
151	      background: var(--kbd-bg);
152	      border: 1px solid transparent;
153	      border-radius: 0.25rem;
154	      font-family: monospace;
155	      font-size: 0.75em;
156	    }
157	  </style>
158	</head>
159	<body>
160	  <main>
161	    <button type="button" aria-label="Change circle color" aria-describedby="status hint">
162	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
163	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
164	      </svg>
165	    </button>
166	    <p class="status" id="status" role="status">Blue</p>
167	    <p class="hint" id="hint">Click to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>)</p>
168	  </main>
169	  <script>
170	    const button = document.querySelector('button');
171	    const status = document.querySelector('.status');
172	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
173	    const storageKey = 'circle-color';
174	
175	    function loadColor() {
176	      try {
177	        return localStorage.getItem(storageKey);
178	      } catch {
179	        return null;
180	      }
181	    }
182	
183	    function saveColor(color) {
184	      try {
185	        localStorage.setItem(storageKey, color);
186	      } catch {}
187	    }
188	
189	    let index = Math.max(colors.indexOf(loadColor()), 0);
190	
191	    function applyColor() {
192	      const color = colors[index];
193	      if (color === 'blue') {
194	        delete button.dataset.color;
195	      } else {
196	        button.dataset.color = color;
197	      }
198	      status.textContent = color[0].toUpperCase() + color.slice(1);
199	    }
200	
201	    function changeColor() {
202	      index = (index + 1) % colors.length;
203	      applyColor();
204	      saveColor(colors[index]);
205	
206	      button.classList.remove('color-changed');
207	      void button.offsetWidth;
208	      button.classList.add('color-changed');
209	    }
210	
211	    applyColor();
212	
213	    button.addEventListener('click', changeColor);
214	    button.addEventListener('animationend', () => {
215	      button.classList.remove('color-changed');
216	    });
217	  </script>
218	</body>
219	</html>
